const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS="*{box-sizing:border-box}\n.card{width:100%;height:100%;display:flex;flex-direction:column;padding:12px;color:var(--ink);background:transparent;font:13px/1.45 system-ui,-apple-system,\"PingFang SC\",\"Microsoft YaHei\",sans-serif;overflow:hidden;min-width:0;min-height:0}\n.card[data-size=\"3x6\"],.card[data-size=\"6x6\"]{padding:16px}\n.card p,.card h3,.card ol{margin:0}\n\n.btn{appearance:none;font:inherit;font-size:12px;font-weight:600;height:30px;padding:0 10px;border-radius:9px;border:1px solid var(--line);background:var(--button-paper,var(--paper));color:var(--ink);cursor:pointer;white-space:nowrap;min-width:0;flex:0 0 auto}\n.btn.primary{background:var(--accent);color:var(--on-accent);border-color:transparent;flex:1 1 auto}\n.btn.sq{width:30px;padding:0;font-size:16px;line-height:1}\n.btn:disabled{opacity:.4;cursor:default}\n.btn:focus-visible,.wk:focus-visible,.ta:focus-visible,.dt:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n\n.home,.hist,.ed,.col{flex:1;min-height:0;min-width:0;display:flex;flex-direction:column;gap:8px}\n.home.row{flex-direction:row;gap:12px}\n.hm-main{flex:1;min-width:0;min-height:0;display:flex;flex-direction:column;gap:6px}\n.hm-side{width:118px;flex:none;display:flex;flex-direction:column;justify-content:space-between;align-items:flex-start;gap:8px}\n.hm-side .actions{width:100%}\n.hd{display:flex;align-items:center;gap:8px;min-width:0;flex:none}\n.ttl{flex:1;min-width:0;font-size:15px;font-weight:800;letter-spacing:.02em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.chip{flex:none;font-size:10px;padding:2px 8px;border-radius:999px;border:1px solid var(--line);color:var(--muted);white-space:nowrap}\n.chip.ok{background:var(--soft);color:var(--ink);border-color:transparent}\n.src{flex:none;min-width:0;font-size:11px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.hm-body{flex:1;min-height:0;min-width:0;overflow:auto;display:flex;flex-direction:column;gap:10px}\n.actions{display:flex;gap:6px;flex:none}\n.card[data-size=\"3x6\"] .actions,.hm-side .actions{flex-direction:column}\n.card[data-size=\"3x6\"] .actions .btn,.hm-side .actions .btn{flex:none;width:100%}\n\n.focus{flex:1 0 auto;background:var(--panel-paper);border:1px solid var(--line);border-radius:12px;padding:8px 10px}\nol.focus-list{list-style:none;padding:8px 10px;display:flex;flex-direction:column;gap:7px;justify-content:flex-start}\n.focus-item{display:flex;gap:8px;align-items:flex-start;min-width:0}\n.dot{flex:none;width:18px;height:18px;margin-top:1px;border-radius:50%;background:var(--accent);color:var(--on-accent);font-size:11px;font-weight:700;display:grid;place-items:center}\n.focus-text{min-width:0;overflow-wrap:anywhere;font-size:14px;font-weight:600;line-height:1.4}\n.card[data-size=\"3x6\"] .focus-text,.card[data-size=\"6x6\"] .focus-text{font-size:16px}\n.empty{display:flex;flex-direction:column;justify-content:center;align-items:center;text-align:center;gap:6px;padding:10px}\n.empty-t{font-weight:700;font-size:13px}\n.empty-s{color:var(--muted);font-size:11px;overflow-wrap:anywhere}\n.grow{flex:1}\n.extras{display:flex;flex-direction:column;gap:8px;flex:none}\n\n.sec{background:var(--panel-paper);border:1px solid var(--line);border-radius:10px;padding:7px 10px;flex:none}\n.sec h3{font-size:11px;color:var(--muted);font-weight:700;letter-spacing:.04em;margin-bottom:3px}\n.sec.next{background:var(--soft);border-color:transparent}\n.sec.next h3{color:var(--ink)}\n.txt{white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px}\n.txt.none{color:var(--muted)}\n.upd{font-size:10px;color:var(--muted);text-align:right;flex:none}\n\n\n.hist{flex-direction:row;gap:10px}\n.hist.narrow{flex-direction:column}\n.lcol{flex:none}\n.hist:not(.narrow) .lcol{width:150px}\n.hist.narrow .lcol{flex:1;width:auto}\n.dcol{flex:1}\n.lst{flex:1;min-height:0;overflow:auto;display:flex;flex-direction:column;gap:6px}\n.wk{appearance:none;font:inherit;text-align:left;display:flex;flex-direction:column;gap:2px;padding:7px 9px;border-radius:10px;border:1px solid var(--line);background:var(--panel-paper);color:var(--ink);cursor:pointer;min-width:0;flex:none;width:100%}\n.wk.on{background:var(--soft);border-color:var(--accent)}\n.wk-l{font-weight:700;font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100%}\n.wk-row{display:flex;align-items:center;gap:5px;min-width:0}\n.wk-s{font-size:11px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0}\n.tag{flex:none;font-size:10px;line-height:15px;padding:0 6px;border-radius:999px;background:var(--accent);color:var(--on-accent);font-weight:700}\n.dhd{display:flex;align-items:center;gap:6px;min-width:0;flex:none}\n.dl{flex:1;min-width:0;font-weight:800;font-size:14px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.dbody{flex:1;min-height:0;min-width:0;overflow:auto;display:flex;flex-direction:column;gap:8px}\n.dft{display:flex;gap:6px;flex:none}\n.dft .btn.sq{width:38px}\n\n.ebody{flex:1;min-height:0;min-width:0;overflow:auto;display:flex;flex-direction:column;gap:8px}\n.fld{display:flex;flex-direction:column;gap:3px;min-width:0;flex:none}\n.lb{font-size:11px;font-weight:700;color:var(--muted)}\n.ta,.dt{width:100%;font:inherit;font-size:13px;color:var(--ink);background:var(--paper);border:1px solid var(--line);border-radius:9px;padding:6px 8px;min-width:0}\n.ta{min-height:76px;resize:vertical;line-height:1.4}\n.dt{height:32px}\n.hd .dt{width:132px;height:28px;padding:2px 6px;font-size:12px;flex:none}\n.wkl{flex:1;text-align:right}\n.err{flex:none;font-size:11px;color:var(--ink);overflow-wrap:anywhere}\n.err:empty{display:none}\n.err:not(:empty)::before{content:\"\u63d0\u793a\uff1a\";font-weight:700}\n.eft{display:flex;align-items:center;gap:6px;flex:none}\n.sp{flex:1}\n.eft .btn.primary{flex:0 0 auto;min-width:56px}\n.eft .btn{height:30px}\n\n.card[data-size=\"3x3\"]{padding:10px}\n.card[data-size=\"3x3\"] .ttl{font-size:14px}\n.card[data-size=\"3x3\"] .btn{padding:0 8px}\n.card[data-size=\"3x3\"] .focus-text{font-size:13px}\n.card[data-size=\"3x3\"] .ed,.card[data-size=\"3x3\"] .home,.card[data-size=\"3x3\"] .hist{gap:6px}\n\n.card[data-size=\"6x3\"] .ebody{flex-direction:row;overflow:hidden;gap:8px}\n.card[data-size=\"6x3\"] .fld{flex:1;min-height:0}\n.card[data-size=\"6x3\"] .ta{flex:1;min-height:0;resize:none}\n.card[data-size=\"6x3\"] .ed{gap:6px}\n.card[data-size=\"6x3\"] .hist:not(.narrow) .lcol{width:138px}\n\n.card[data-size=\"3x6\"] .ta{min-height:96px}\n.card[data-size=\"6x6\"] .ta{min-height:96px}\n.card[data-size=\"6x6\"] .hist:not(.narrow) .lcol{width:160px}\n.card[data-size=\"6x6\"],.card[data-size=\"3x6\"]{gap:0}\n";
function parseDay(s){
  const m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(s||'');
  if(!m)return null;
  const d=new Date(+m[1],+m[2]-1,+m[3]);
  return isNaN(d.getTime())?null:d;
}
function fmtDay(d){
  return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
}
function weekStartOf(s){
  const d=parseDay(s);
  if(!d)return null;
  d.setDate(d.getDate()-((d.getDay()+6)%7));
  return fmtDay(d);
}
function weekLabel(ws,short){
  const a=parseDay(ws);
  if(!a)return '';
  const b=new Date(a.getFullYear(),a.getMonth(),a.getDate()+6);
  const y=new Date().getFullYear();
  if(short){
    return (a.getFullYear()!==y?a.getFullYear()+'/':'')+(a.getMonth()+1)+'/'+a.getDate()+'–'+(b.getMonth()+1)+'/'+b.getDate();
  }
  const head=(a.getFullYear()!==y?a.getFullYear()+'年':'')+(a.getMonth()+1)+'月'+a.getDate()+'日';
  const tail=(b.getFullYear()!==a.getFullYear()?b.getFullYear()+'年':'')+(b.getMonth()+1)+'月'+b.getDate()+'日';
  return head+' – '+tail;
}
function planLines(t){
  return String(t||'').split('\n').map(x=>x.replace(/^\s*(?:[-•·*]\s*|\d+、\s*|\d+[.)]\s+)/,'').trim()).filter(Boolean);
}
function listOf(s){
  const r=s&&Array.isArray(s.reviews)?s.reviews.filter(x=>x&&x.id&&parseDay(x.weekStart)):[];
  return r.slice().sort((a,b)=>a.weekStart<b.weekStart?1:(a.weekStart>b.weekStart?-1:0));
}

function mount(ctx){
  const {root,el,state,ui,uid,day,commit,redraw,size}=ctx;
  const h=(t,a,...k)=>el(t,a||{},...k.filter(x=>x!==null&&x!==undefined&&x!==false));
  const reviews=listOf(state);
  const wide=size==='6x3'||size==='6x6';
  const tall=size==='3x6'||size==='6x6';
  const small=size==='3x3';
  const thisWeek=weekStartOf(day());
  const cur=reviews.find(r=>r.weekStart===thisWeek)||null;
  const latest=reviews[0]||null;
  const wl=ws=>weekLabel(ws,small);
  if(!ui.view)ui.view='home';

  function go(view,extra){
    ui.view=view;
    Object.assign(ui,extra||{});
    redraw();
  }
  function btn(label,onclick,cls,aria){
    const a={type:'button',class:'btn'+(cls?' '+cls:''),onclick};
    if(aria)a['aria-label']=aria;
    return el('button',a,label);
  }
  function freeDate(){
    if(!reviews.some(r=>r.weekStart===thisWeek))return day();
    let w=thisWeek;
    while(reviews.some(r=>r.weekStart===w)){
      const d=parseDay(w);
      d.setDate(d.getDate()-7);
      w=fmtDay(d);
    }
    return w;
  }
  function openEditor(rec,date){
    ui.draft=rec
      ?{id:rec.id,date:rec.weekStart,progress:rec.progress||'',difficulty:rec.difficulty||'',nextPlan:rec.nextPlan||''}
      :{id:null,date:date||day(),progress:'',difficulty:'',nextPlan:''};
    ui.back=ui.view==='history'?'history':'home';
    go('edit');
  }
  function sec(title,txt,cls){
    const has=!!(txt&&String(txt).trim());
    return h('section',{class:'sec'+(cls?' '+cls:'')},
      h('h3',{},title),
      h('p',{class:'txt'+(has?'':' none')},has?String(txt):'未填写'));
  }


  function homeView(){
    const lines=latest?planLines(latest.nextPlan):[];
    let focus;
    if(!latest){
      focus=h('div',{class:'focus empty'},
        h('p',{class:'empty-t'},'还没有复盘'),
        h('p',{class:'empty-s'},'写下这周的进步、困难和下周要调整的事，下周重点会显示在这里。'));
    }else if(!lines.length){
      focus=h('div',{class:'focus empty'},
        h('p',{class:'empty-t'},'没有写下周要调整的事'),
        h('p',{class:'empty-s'},'最近一次复盘（'+wl(latest.weekStart)+'）这一项是空的。'));
    }else{
      focus=h('ol',{class:'focus focus-list'},...lines.map((t,i)=>
        h('li',{class:'focus-item'},
          h('span',{class:'dot'},String(i+1)),
          h('span',{class:'focus-text'},t))));
    }
    const src=latest?h('div',{class:'src'},'来自 '+wl(latest.weekStart)+' 的复盘'):null;
    const chip=h('span',{class:'chip'+(cur?' ok':'')},cur?'本周已复盘':'本周未复盘');
    const extras=(tall&&latest)?h('div',{class:'extras'},
      sec('上次的进步',latest.progress),
      sec('上次的困难',latest.difficulty)):null;
    const writeLabel=cur?(small?'改复盘':'改本周复盘'):(small?'写复盘':'写本周复盘');
    const histLabel=small?'往期':('往期记录'+(reviews.length?'（'+reviews.length+'）':''));
    const actions=h('div',{class:'actions'},
      btn(writeLabel,()=>openEditor(cur),'primary'),
      btn(histLabel,()=>go('history',{detailId:null}),'ghost'));
    if(size==='6x3'){
      return h('div',{class:'home row'},
        h('div',{class:'hm-main'},
          h('div',{class:'hd'},h('span',{class:'ttl'},'下周重点')),
          src,
          h('div',{class:'hm-body'},focus)),
        h('div',{class:'hm-side'},chip,actions));
    }
    return h('div',{class:'home'},
      h('div',{class:'hd'},h('span',{class:'ttl'},'下周重点'),chip),
      src,
      h('div',{class:'hm-body'},focus,extras),
      actions);
  }

  function weekItem(r,active){
    const first=String(r.progress||'').split('\n').map(x=>x.trim()).find(Boolean)||'';
    return h('button',{type:'button',class:'wk'+(active?' on':''),onclick:()=>{ui.detailId=r.id;redraw();}},
      h('span',{class:'wk-l'},wl(r.weekStart)),
      h('span',{class:'wk-row'},
        r.weekStart===thisWeek?h('span',{class:'tag'},'本周'):null,
        h('span',{class:'wk-s'},first||'（没写进步）')));
  }

  function detailCol(r,narrow){
    const i=reviews.indexOf(r);
    const older=reviews[i+1]||null;
    const newer=i>0?reviews[i-1]:null;
    const prev=btn('‹',()=>{if(older){ui.detailId=older.id;redraw();}},'sq','更早一周');
    const next=btn('›',()=>{if(newer){ui.detailId=newer.id;redraw();}},'sq','更近一周');
    prev.disabled=!older;
    next.disabled=!newer;
    return h('div',{class:'col dcol'},
      h('div',{class:'dhd'},
        narrow?btn('‹',()=>go('history',{detailId:null}),'sq','回到列表'):null,
        h('span',{class:'dl'},wl(r.weekStart)),
        r.weekStart===thisWeek?h('span',{class:'tag'},'本周'):null),
      h('div',{class:'dbody'},
        sec('本周的进步',r.progress),
        sec('遇到的困难',r.difficulty),
        sec('下周要调整的事',r.nextPlan,'next'),
        r.updated?h('div',{class:'upd'},'更新于 '+r.updated):null),
      h('div',{class:'dft'},prev,btn('编辑这周',()=>openEditor(r),'primary'),next));
  }

  function listCol(active){
    return h('div',{class:'col lcol'},
      h('div',{class:'hd'},
        btn('‹',()=>go('home'),'sq','返回'),
        h('span',{class:'ttl'},'往期复盘'),
        btn('＋',()=>openEditor(null,freeDate()),'sq','补写一周复盘')),
      h('div',{class:'lst'},...reviews.map(r=>weekItem(r,!!active&&active.id===r.id))));
  }

  function historyView(){
    if(!reviews.length){
      return h('div',{class:'col full'},
        h('div',{class:'hd'},btn('‹',()=>go('home'),'sq','返回'),h('span',{class:'ttl'},'往期复盘')),
        h('div',{class:'focus empty grow'},
          h('p',{class:'empty-t'},'还没有往期复盘'),
          h('p',{class:'empty-s'},'保存的每一周都会按周列在这里。'),
          btn('写第一条复盘',()=>openEditor(null,day()),'primary')));
    }
    const sel=reviews.find(r=>r.id===ui.detailId)||null;
    if(wide){
      const a=sel||reviews[0];
      return h('div',{class:'hist'},listCol(a),detailCol(a,false));
    }
    return h('div',{class:'hist narrow'},sel?detailCol(sel,true):listCol(null));
  }


  function editView(){
    const d=ui.draft;
    const hasId=!!d.id&&reviews.some(r=>r.id===d.id);
    const wkNode=h('span',{class:'src wkl'},wl(weekStartOf(d.date))||'请选日期');
    const errNode=h('div',{class:'err','aria-live':'polite'},'');
    const showErr=m=>{errNode.textContent=m;};
    function onDate(e){
      d.date=e.target.value;
      const w=weekStartOf(d.date);
      wkNode.textContent=w?wl(w):'请选日期';
    }
    const dateIn=h('input',{class:'dt',type:'date',value:d.date||'',onchange:onDate,oninput:onDate,'aria-label':'所属周内任意一天'});
    const field=(key,label,ph)=>h('label',{class:'fld'},
      h('span',{class:'lb'},label),
      h('textarea',{class:'ta',placeholder:ph,value:d[key]||'',oninput:e=>{d[key]=e.target.value;}}));
    const f1=field('progress','本周的进步','这周做成了什么、哪里变好了');
    const f2=field('difficulty','遇到的困难','卡在哪里、什么拖慢了你');
    const f3=field('nextPlan','下周要调整的事','每行一件，会作为下周重点显示');

    function cancel(){go(ui.back||'home',{draft:null});}
    const saveBtn=btn('保存',save,'primary');
    function save(){
      const ws=weekStartOf(d.date);
      const p=String(d.progress||'').trim();
      const q=String(d.difficulty||'').trim();
      const n=String(d.nextPlan||'').trim();
      if(!ws){showErr('请先选择所属日期。');return;}
      if(!p&&!q&&!n){showErr('三项至少写一项再保存。');return;}
      if(reviews.some(r=>r.weekStart===ws&&r.id!==d.id)){
        showErr(wl(ws)+' 已有复盘，请换一周，或到往期记录里编辑它。');
        return;
      }
      const id=d.id||uid();
      const rec={id,weekStart:ws,progress:p,difficulty:q,nextPlan:n,updated:day()};
      const nextUi=ui.back==='history'
        ?{view:'history',detailId:id,draft:null,back:null}
        :{view:'home',detailId:null,draft:null,back:null};
      saveBtn.disabled=true;
      showErr('');
      commit(s=>{
        const list=(s&&Array.isArray(s.reviews)?s.reviews:[]).filter(x=>x&&x.id!==id);
        list.push(rec);
        return Object.assign({},s,{reviews:list});
      },nextUi).then(ok=>{
        if(!ok){saveBtn.disabled=false;showErr('没有保存成功，请再试一次。');}
      }).catch(e=>{
        saveBtn.disabled=false;
        showErr('保存失败：'+((e&&e.message)||'请再试一次')+'。内容还在，可以重试。');
      });
    }

    let armed=false;
    const delBtn=hasId?btn('删除',onDel,'ghost'):null;
    function onDel(){
      if(!armed){
        armed=true;
        delBtn.textContent='确认删除';
        showErr('再点一次「确认删除」，这一周的复盘会被删掉。');
        return;
      }
      delBtn.disabled=true;
      commit(s=>{
        const list=(s&&Array.isArray(s.reviews)?s.reviews:[]).filter(x=>x&&x.id!==d.id);
        return Object.assign({},s,{reviews:list});
      },{view:'history',detailId:null,draft:null,back:null}).then(ok=>{
        if(!ok){delBtn.disabled=false;showErr('没有删除成功，请再试一次。');}
      }).catch(e=>{
        delBtn.disabled=false;
        showErr('删除失败：'+((e&&e.message)||'请再试一次')+'。');
      });
    }

    const head=size==='6x3'
      ?h('div',{class:'hd'},h('span',{class:'ttl'},hasId?'编辑复盘':'写复盘'),wkNode,dateIn)
      :h('div',{class:'hd'},h('span',{class:'ttl'},hasId?'编辑复盘':'写复盘'),wkNode);
    const body=size==='6x3'
      ?h('div',{class:'ebody'},f1,f2,f3)
      :h('div',{class:'ebody'},f1,f2,f3,
        h('label',{class:'fld'},h('span',{class:'lb'},'所属周（选该周内任意一天）'),dateIn));
    const foot=h('div',{class:'eft'},delBtn,h('span',{class:'sp'}),btn('取消',cancel,'ghost'),saveBtn);
    return h('div',{class:'ed'},head,body,errNode,foot);
  }

  let view;
  if(ui.view==='edit'&&ui.draft)view=editView();
  else if(ui.view==='history')view=historyView();
  else view=homeView();
  root.append(view);
